from sympy import totient, isprime, factorint
def phi(n): return int(totient(n))

# 1. 6*$7^{(c}$-1)+1 primality
for c in range(1,11):
    val=6*7**(c-1)+1
    print(f'c={c}: {val} -> {"PRIME" if isprime(val) else f"composite: {factorint(val)}"}')

# 2. Partners for n=530964
partners=[m for m in range(2,600000) if m!=530964 and phi(m)==phi(530964)]
print(f'n=530964 partners (first 5): {partners[:5]}')
for m in partners[:5]: print(f'  {m}={factorint(m)}')

